def safe_divide(nums):
    results = []
    for i in range(len(nums) - 1):
        try:
            result = nums[i] / nums[i + 1]
            results.append(int(result))
        except ZeroDivisionError:
            results.append('X')
    return results

print(safe_divide([10, 2, 0, 5]))

try:
    x = 1 / 0
except Exception:
    print('Exception')
except ZeroDivisionError:
    print('Zero')
finally:
    print('done')

